import logging
import re
import time
from typing import Callable, Iterator, List, Optional
from pydantic import BaseModel
from shared.faiss_store import SearchResult
from shared.config import config

logger = logging.getLogger("LLMGenerator")


class RAGResponse(BaseModel):
    """Encapsulates final answer generated by LLM along with cited vector context sources."""
    query: str
    answer: str
    sources: List[SearchResult]
    provider_used: str
    model_name: str


class StreamEvent(BaseModel):
    """One item of a streamed answer: a text delta, a reset (discard text so far), or the final done marker."""
    type: str  # "token" | "reset" | "done"
    text: str = ""
    provider_used: str = ""
    model_name: str = ""


class LLMGenerator:
    """Pluggable LLM interface supporting Gemini API, Claude API, and Mock Fallback."""

    def __init__(self, provider: Optional[str] = None):
        self.provider = (provider or config.LLM_PROVIDER).lower()

    def generate_answer(self, query: str, context_chunks: List[SearchResult]) -> RAGResponse:
        """Constructs RAG context prompt and queries selected LLM provider."""
        formatted_context = self._format_context(context_chunks)
        prompt = self._build_prompt(query, formatted_context)

        if self.provider == "gemini" and config.GEMINI_API_KEY:
            return self._call_gemini(query, prompt, context_chunks)
        elif self.provider == "claude" and config.ANTHROPIC_API_KEY:
            return self._call_claude(query, prompt, context_chunks)
        else:
            return self._call_mock(query, context_chunks)

    def stream_answer(
        self,
        query: str,
        context_chunks: List[SearchResult],
        should_stop: Callable[[], bool] = lambda: False,
    ) -> Iterator[StreamEvent]:
        """Streams the answer as StreamEvents (blocking generator; run it in a thread).

        If a provider fails or refuses part-way, a "reset" event tells the client to drop the partial text,
        then the mock answer is streamed instead, so a stream always ends with "done".
        """
        prompt = self._build_prompt(query, self._format_context(context_chunks))
        if self.provider == "gemini" and config.GEMINI_API_KEY:
            source = self._stream_gemini(prompt)
        elif self.provider == "claude" and config.ANTHROPIC_API_KEY:
            source = self._stream_claude(prompt)
        else:
            yield from self._stream_mock(query, context_chunks, should_stop)
            return

        emitted = False
        try:
            for event in source:
                if should_stop():
                    return
                emitted = emitted or event.type == "token"
                yield event
            return
        except Exception as e:
            logger.warning(f"{self.provider} streaming failed ({e}). Falling back to Mock generator.")
        finally:
            source.close()
        if emitted:
            yield StreamEvent(type="reset")
        yield from self._stream_mock(query, context_chunks, should_stop)

    def _stream_mock(self, query: str, context_chunks: List[SearchResult], should_stop: Callable[[], bool]) -> Iterator[StreamEvent]:
        """Streams the mock answer word by word so the UI path is exercised without an API key."""
        resp = self._call_mock(query, context_chunks)
        for piece in re.findall(r"\S+\s*", resp.answer):
            if should_stop():
                return
            yield StreamEvent(type="token", text=piece)
            time.sleep(0.01)
        yield StreamEvent(type="done", provider_used=resp.provider_used, model_name=resp.model_name)

    def _stream_gemini(self, prompt: str) -> Iterator[StreamEvent]:
        from google import genai
        client = genai.Client(api_key=config.GEMINI_API_KEY)
        for chunk in client.models.generate_content_stream(model=config.GEMINI_MODEL, contents=prompt):
            if chunk.text:
                yield StreamEvent(type="token", text=chunk.text)
        yield StreamEvent(type="done", provider_used="Google Gemini", model_name=config.GEMINI_MODEL)

    def _stream_claude(self, prompt: str) -> Iterator[StreamEvent]:
        import anthropic
        client = anthropic.Anthropic(api_key=config.ANTHROPIC_API_KEY)
        # A server-side fallback continues on the same stream, so deltas keep arriving across a model switch
        with client.beta.messages.stream(
            model=config.CLAUDE_MODEL,
            max_tokens=16000,
            betas=["server-side-fallback-2026-07-01"],
            fallbacks="default",
            output_config={"effort": config.CLAUDE_EFFORT},
            messages=[{"role": "user", "content": prompt}],
        ) as stream:
            for text in stream.text_stream:
                yield StreamEvent(type="token", text=text)
            final = stream.get_final_message()
        if final.stop_reason == "refusal":
            raise RuntimeError(f"request refused ({getattr(final.stop_details, 'category', None)})")
        yield StreamEvent(type="done", provider_used="Anthropic Claude", model_name=final.model)

    def _format_context(self, context_chunks: List[SearchResult]) -> str:
        if not context_chunks:
            return "No relevant context documents found."
        
        context_str = ""
        for i, chunk in enumerate(context_chunks, 1):
            shard_info = f" [Shard: {chunk.shard_id}]" if chunk.shard_id else ""
            context_str += f"[Source {i}{shard_info} (Doc: {chunk.doc_id}, Score: {chunk.score:.4f})]:\n{chunk.text}\n\n"
        return context_str.strip()

    def _build_prompt(self, query: str, context: str) -> str:
        return (
            "You are a precise AI research assistant answering questions using only the provided context snippets.\n"
            "If the context does not contain enough information to answer, state clearly that information is missing.\n\n"
            f"--- CONTEXT START ---\n{context}\n--- CONTEXT END ---\n\n"
            f"USER QUESTION: {query}\n\n"
            "ANSWER:"
        )

    def _call_mock(self, query: str, context_chunks: List[SearchResult]) -> RAGResponse:
        """Fallback offline mock answer generator summarizing retrieved sources."""
        if not context_chunks:
            answer = "Mock LLM Response: No relevant documents were retrieved from the vector index for your query."
        else:
            top_source = context_chunks[0]
            shards = sorted({c.shard_id for c in context_chunks if c.shard_id})
            answer = (
                f"Mock LLM Response (Synthesized from {len(context_chunks)} retrieved chunks across {len(shards)} shard(s)):\n"
                f"Based on doc '{top_source.doc_id}' (relevance score {top_source.score:.4f}):\n"
                f"\"{top_source.text}\"\n\n"
                f"Summary: The document indicates that {top_source.text[:150]}..."
            )
            
        return RAGResponse(
            query=query,
            answer=answer,
            sources=context_chunks,
            provider_used="Mock (Local Fallback)",
            model_name="mock-generator-v1"
        )

    def _call_gemini(self, query: str, prompt: str, context_chunks: List[SearchResult]) -> RAGResponse:
        try:
            from google import genai
            client = genai.Client(api_key=config.GEMINI_API_KEY)
            response = client.models.generate_content(
                model=config.GEMINI_MODEL,
                contents=prompt,
            )
            return RAGResponse(
                query=query,
                answer=response.text or "No text generated.",
                sources=context_chunks,
                provider_used="Google Gemini",
                model_name=config.GEMINI_MODEL
            )
        except Exception as e:
            logger.warning(f"Gemini API call failed ({e}). Falling back to Mock generator.")
            return self._call_mock(query, context_chunks)

    def _call_claude(self, query: str, prompt: str, context_chunks: List[SearchResult]) -> RAGResponse:
        try:
            import anthropic
            client = anthropic.Anthropic(api_key=config.ANTHROPIC_API_KEY)
            # Server-side fallback re-runs the request on another model if a safety classifier declines it
            response = client.beta.messages.create(
                model=config.CLAUDE_MODEL,
                max_tokens=16000,
                betas=["server-side-fallback-2026-07-01"],
                fallbacks="default",
                output_config={"effort": config.CLAUDE_EFFORT},
                messages=[{"role": "user", "content": prompt}],
            )
            if response.stop_reason == "refusal":
                raise RuntimeError(f"request refused ({getattr(response.stop_details, 'category', None)})")
            answer = "".join(block.text for block in response.content if block.type == "text").strip()
            return RAGResponse(
                query=query,
                answer=answer or "No text generated.",
                sources=context_chunks,
                provider_used="Anthropic Claude",
                model_name=response.model,
            )
        except Exception as e:
            logger.warning(f"Claude API call failed ({e}). Falling back to Mock generator.")
            return self._call_mock(query, context_chunks)


# Global singleton instance
llm_generator = LLMGenerator()
